15	const (
16		wslSourceNAT          = "WSL2 (VM), not the Windows host · NAT mode"
17		wslSourceMirrored     = "WSL2 (VM), not the Windows host · mirrored mode"
18		wslSourceUndetermined = "WSL2 (VM), not the Windows host · mode unknown"
19		wslHostCell           = "172.27.128.1 — Windows host (virtual switch)"
20	)
21	
22	var (
23		wslGW        = netip.MustParseAddr("172.27.128.1")
24		wslInfoNAT   = wslenv.Info{WSL2: true, Mode: wslenv.ModeNAT, NATInterface: "eth0", NATGateway: wslGW}
25		wslRoute     = &pathRoute{Known: true, Interface: "eth0", Source: netip.MustParseAddr("172.27.130.5"), Gateway: wslGW}
26		wslHop1      = nettrace.Hop{TTL: 1, Kind: nettrace.HopRouter, Addr: wslGW}
27		wslHop1Quiet = nettrace.Hop{TTL: 1, Kind: nettrace.HopSilent}
28		wslHop2      = nettrace.Hop{TTL: 2, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("192.168.1.1")}
29		wslHop3GW    = nettrace.Hop{TTL: 3, Kind: nettrace.HopRouter, Addr: wslGW}
30	)
31	
32	// wslCells returns the address cell of every step.
33	func wslCells(steps []pathStep) []string {
34		cells := make([]string, len(steps))
35		for i, s := range steps {
36			cells[i] = s.addressCell()
37		}
38		return cells
39	}
40	
41	// wslStep returns the first step of the kind, or a step of kind -1.
42	func wslStep(steps []pathStep, kind pathStepKind) pathStep {
43		for _, s := range steps {
44			if s.Kind == kind {
45				return s
46			}
47		}
48		return pathStep{Kind: -1}
49	}
50	
51	// wslLabelled reports whether a cell other than the source row names the Windows host.
52	func wslLabelled(steps []pathStep) bool {
53		for _, s := range steps {
54			if s.Kind != stepSource && strings.Contains(s.addressCell(), "Windows host") {
55				return true
56			}
57		}
58		return false
59	}
