1	package netdiag
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"reflect"
9		"strings"
10		"syscall"
11		"testing"
12	
13		tea "charm.land/bubbletea/v2"
14		"github.com/charmbracelet/x/ansi"
15	
16		"github.com/anthnel/devdesk/internal/nettrace"
17		"github.com/anthnel/devdesk/internal/ui/testutil"
18	)
19	
20	// DEVDESK-335 step 4: a silent end of the path is one row, not a wall of rows.
21	
22	const lastAnswerTag = " · last to answer"
23	
24	// nrHops builds TTLs 1..total: routers up to and including routers, then the
25	// given kind (HopSilent by default) for the rest.
26	func nrHops(total, routers int, tail ...nettrace.HopKind) []nettrace.Hop {
27		kind := nettrace.HopSilent
28		if len(tail) > 0 {
29			kind = tail[0]
30		}
31		out := make([]nettrace.Hop, 0, total)
32		for ttl := 1; ttl <= total; ttl++ {
33			if ttl <= routers {
34				out = append(out, nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr(fmt.Sprintf("10.0.0.%d", ttl))})
35				continue
36			}
37			out = append(out, nettrace.Hop{TTL: ttl, Kind: kind})
38		}
39		return out
40	}
41	
42	// nrTerminalBeforeTail is the shape nettrace.Result gives after a deadline once
43	// a terminal hop is known: 1 router, 2 unresolved, 3 the terminal hop (kind),
44	// then TTLs 4..30 unresolved.
45	func nrTerminalBeforeTail(kind nettrace.HopKind) []nettrace.Hop {
46		hops := nrHops(30, 1, nettrace.HopUnresolved)
47		hops[2] = nettrace.Hop{TTL: 3, Kind: kind, Addr: netip.MustParseAddr("10.0.0.3")}
48		return hops
49	}
50	
51	func nrResult(o nettrace.Outcome, hops []nettrace.Hop) *nettrace.Result {
52		return &nettrace.Result{Outcome: o, Hops: hops}
53	}
54	
55	// nrRows is pathSteps + withNoResponse for res, as refreshSteps composes them.
56	func nrRows(res *nettrace.Result) []pathStep {
57		var hops []nettrace.Hop
58		if res != nil {
59			hops = res.Hops
60		}
61		route := &pathRoute{Known: true, Interface: "eth0", Gateway: netip.MustParseAddr("10.0.0.1")}
62		return withNoResponse(pathSteps(nil, route, hops), res)
63	}
64	
65	func nrHopRows(steps []pathStep) []pathStep {
66		var out []pathStep
67		for _, s := range steps {
68			if s.Kind >= stepHop {
69				out = append(out, s)
70			}
71		}
72		return out
73	}
74	
75	// nrCells is "hop|step|address|rtt" per hop-level row.
76	func nrCells(steps []pathStep) []string {
77		var out []string
78		for _, s := range nrHopRows(steps) {
79			out = append(out, s.hopCell()+"|"+s.stepCell()+"|"+s.addressCell()+"|"+s.rttCell())
80		}
81		return out
82	}
83	
84	func TestWithNoResponse(t *testing.T) {
85		deadlineMixed := nrHops(8, 3)
86		deadlineMixed[5].Kind = nettrace.HopUnresolved
87		deadlineMixed[7].Kind = nettrace.HopUnresolved
88		withError := nrHops(6, 2)
89		withError[2] = nettrace.Hop{TTL: 3, Kind: nettrace.HopError, Err: errors.New("send failed")}
90		middle := nrHops(6, 5)
91		middle[2].Kind = nettrace.HopSilent
92		middle[2].Addr = netip.Addr{}
93	
94		tests := []struct {
95			name     string
96			res      *nettrace.Result
97			wantTail pathTail
98			wantOK   bool
99			wantRows int    // hop-level rows after grouping
100			wantLast string // address cell of the last-to-answer row ("" = none)
101			wantAddr string // address cell of the grouped row
102			wantHop  string // hop cell of the grouped row
103		}{
104			{"1 to 3 routers then silent", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 3)),
105				pathTail{First: 4, Last: 30, Anchor: 3}, true, 4, "10.0.0.3" + lastAnswerTag,
106				"no response beyond hop 3 (hops 4 to 30)", "4+"},
107			{"criterion 3: one router then silent", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 1)),
108				pathTail{First: 2, Last: 30, Anchor: 1}, true, 2, "10.0.0.1" + lastAnswerTag,
109				"no response beyond hop 1 (hops 2 to 30)", "2+"},
110			{"nothing answered", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 0)),
111				pathTail{First: 1, Last: 30}, true, 1, "",
112				"no response from any hop (hops 1 to 30)", "1+"},
113			{"a silent hop in the middle stays", nrResult(nettrace.OutcomeMaxHops, middle),
114				pathTail{First: 6, Last: 6, Anchor: 5}, true, 6, "10.0.0.5" + lastAnswerTag,
115				"no response beyond hop 5 (hop 6)", "6"},
116			{"single silent hop at the end", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 29)),
117				pathTail{First: 30, Last: 30, Anchor: 29}, true, 30, "10.0.0.29" + lastAnswerTag,
118				"no response beyond hop 29 (hop 30)", "30"},
119			{"router on the last TTL", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 30)),
120				pathTail{}, false, 30, "", "", ""},
121			{"deadline: target answered before the unresolved tail", nrResult(nettrace.OutcomeDeadline, nrTerminalBeforeTail(nettrace.HopTarget)),
122				pathTail{}, false, 2, "", "", ""},
123			{"deadline: unreachable answered before the unresolved tail", nrResult(nettrace.OutcomeDeadline, nrTerminalBeforeTail(nettrace.HopUnreachable)),
124				pathTail{}, false, 2, "", "", ""},
125			{"max hops: unreachable answered before the silent tail", nrResult(nettrace.OutcomeMaxHops, nrTerminalBeforeTail(nettrace.HopUnreachable)),
126				pathTail{}, false, 2, "", "", ""},
127			{"deadline, unresolved mixed with silent", nrResult(nettrace.OutcomeDeadline, deadlineMixed),
128				pathTail{First: 4, Last: 8, Anchor: 3}, true, 4, "10.0.0.3" + lastAnswerTag,
129				"no response beyond hop 3 (hops 4 to 8)", "4+"},
130			{"an error row before the silent end stays", nrResult(nettrace.OutcomeMaxHops, withError),
131				pathTail{First: 4, Last: 6, Anchor: 2}, true, 4, "10.0.0.2" + lastAnswerTag,
