	m, _ := routeResults(t, "example.com")
	m.pathModel.engine.supported = windowsSupported
	m = selectCheck(t, m, netcheck.CheckRoute)

	if sc := m.GetShortcuts(); !testutil.ShortcutEnabled(sc, keymap.Diagnose) {
